// Мастер первого знакомства с SABAK+.
// 1) заставка из финала главы «Башталыш» (тетрадь → страница в линейку → слово SABAK+: сначала контур, потом заливка, без слогана);
// 2) мастер установки в фирменном стиле SABAK+ (mobile-first): шаги, инструкция для своей роли, шпаргалка, настройка, установка;
// 3) экскурсия-подсветка по настоящему интерфейсу («Показать на экране»).
// Показывается один раз после регистрации (признак хранится на устройстве и в таблице consents). Открыть снова: меню профиля → «Как пользоваться SABAK+».
import * as S from './store.js';
import * as API from './api.js';
import * as Privacy from './privacy.js';
import * as A11y from './a11y.js';
import { esc, go } from './common.js';

export const VERSION = 'welcome-1';   // имя записи в consents (до 20 символов)
const FRESH_DAYS = 14;                // автоматически показываем только новым аккаунтам

const W = { open: false, phase: '', page: 0, pages: [], r: null, v: {}, installDone: false, force: false, checkedFor: null, ask: false, raf: 0, timers: [], from: null, tip: 0 };
let root = null;

// ───────────────────────── помощники ─────────────────────────
const st = () => S.state();
const ky = () => st().prefs.lang === 'ky';
const T = (ru, k) => (ky() && k ? k : ru);
const reduced = () => document.documentElement.dataset.motion === 'reduced';
const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const seg = (p, a, b) => clamp((p - a) / (b - a));
const ease = { out: t => 1 - Math.pow(1 - t, 3), inOut: t => (t < .5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2) };
const $ = s => root && root.querySelector(s);
const setv = (el, k, v) => { if (el) el.style.setProperty(k, (+v).toFixed(3)); };
const lsKey = id => 'sabak.welcome.' + id;
const seenLocal = id => { try { return localStorage.getItem(lsKey(id)) === '1'; } catch { return false; } };
const markLocal = id => { try { localStorage.setItem(lsKey(id), '1'); } catch {} };
const later = (fn, ms) => { const t = setTimeout(fn, ms); W.timers.push(t); return t; };
const clearAnim = () => { cancelAnimationFrame(W.raf); W.timers.forEach(clearTimeout); W.timers = []; };
const plural5 = n => (n % 10 === 1 && n % 100 !== 11 ? 'пятёрка' : [2, 3, 4].includes(n % 10) && ![12, 13, 14].includes(n % 100) ? 'пятёрки' : 'пятёрок');

const ROLES = { student: ['Ученик', 'Окуучу'], parent: ['Родитель', 'Ата-эне'], teacher: ['Учитель', 'Мугалим'], director: ['Директор', 'Директор'], deputy: ['Завуч', 'Завуч'], super: ['Администратор платформы', 'Платформанын администратору'] };
function roleInfo() {
  const u = st().session || {};
  const key = u.role === 'admin' ? (u.level === 'deputy' ? 'deputy' : 'director') : (u.role || 'student');
  const group = key === 'director' || key === 'deputy' ? 'admin' : key;
  const parts = String(u.name || '').trim().split(/\s+/).filter(Boolean);
  // в живом режиме ФИО хранится как «Фамилия Имя Отчество», в демо — «Имя Фамилия»
  const first = S.isLive() ? (parts[1] || parts[0] || '') : (parts[0] || '');
  const stu = group === 'student' ? st().students.find(s => s.id === u.id) : null;
  return { u, key, group, label: T(...(ROLES[key] || ROLES.student)), first, cls: stu && stu.cls, school: st().school && st().school.name };
}

// ───────────────────────── когда показывать ─────────────────────────
export function menuLabel() { return T('Как пользоваться SABAK+', 'SABAK+ кантип колдонулат'); }
export function forceNext() { W.force = true; }
export function open() { W.force = false; start(); }
export async function maybe() {
  const u = st().session;
  if (W.open || !u || !u.id || u.suspended || u.needsProfile || (u.status && u.status !== 'active')) return;
  if (W.force) { W.force = false; start(); return; }
  if (!S.isLive() || W.checkedFor === u.id) return;
  if (!Privacy.known() || Privacy.needed()) return;          // сначала согласие с политикой данных
  W.checkedFor = u.id;
  if (seenLocal(u.id)) return;
  const created = Date.parse(u.created || '');
  if (!(created > Date.now() - FRESH_DAYS * 864e5)) return;   // старые аккаунты не беспокоим
  let accepted = false;
  try { const r = await API.rpc('consent_status', { p_version: VERSION }); accepted = !!(r && r.ok && r.accepted); } catch {}
  if (accepted) { markLocal(u.id); return; }
  const now = st().session; if (now && now.id === u.id) start();
}
function remember() {
  const u = st().session; if (u && u.id) markLocal(u.id);
  if (S.isLive()) { try { Promise.resolve(API.rpc('consent_accept', { p_version: VERSION })).catch(() => {}); } catch {} }
}

// ───────────────────────── запуск и закрытие ─────────────────────────
function start() {
  if (W.open || !st().session) return;
  W.open = true; W.page = 0; W.v = {}; W.installDone = false; W.ask = false; W.tip = 0; W.r = roleInfo(); W.pages = buildPages(W.r);
  W.from = document.activeElement;
  root = document.createElement('div'); root.id = 'welcome'; root.className = 'wz';
  document.body.appendChild(root);
  document.documentElement.classList.add('wz-lock');
  const app = document.getElementById('app'); if (app) app.inert = true;
  root.addEventListener('click', onClick);
  renderSplash();
}
function close() {
  clearAnim(); W.open = false; W.phase = '';
  if (root) { root.removeEventListener('click', onClick); root.remove(); root = null; }
  document.documentElement.classList.remove('wz-lock');
  const app = document.getElementById('app'); if (app) app.inert = false;
  try { if (W.from && document.contains(W.from)) W.from.focus(); } catch {}
}
function finish(dest) {
  remember(); close();
  if (!reduced()) { try { A11y.confetti(st().prefs); } catch {} }
  if (dest) go(dest);
}
function skip() { remember(); close(); }

// ───────────────────────── 1. заставка «Башталыш» ─────────────────────────
const hornTile = (color = '#8a6a30', opacity = .09, size = 96) => {
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='${size}' height='${size}' viewBox='0 0 64 64' fill='none' stroke='${color}' stroke-opacity='${opacity}' stroke-width='1.6' stroke-linecap='round'><path d='M32 54C20 54 11 46 11 35 11 24 19 17 28 19c7 1.6 7 10 1 11.5-4 1-7-2-5.5-5'/><path d='M32 54C44 54 53 46 53 35 53 24 45 17 36 19c-7 1.6-7 10-1 11.5 4 1 7-2 5.5-5'/></svg>`;
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
};
function splashHTML() {
  return `<div class="wzs-bg"></div>
  <div class="wzs-stage" id="wzs-stage"><div class="nb" id="nb" aria-hidden="true">
    <div class="nb-back"></div>
    <div class="nb-page nb-right"><div class="ruled"></div>
      <div class="ui-bit grid" id="uig"><b>Математика</b><div class="cells"><i>5</i><i>4</i><i class="x2">5</i><i>3</i></div><small>${T('контрольная ×2', 'көзөмөл ×2')}</small></div></div>
    <div class="nb-page nb-left"><div class="ruled"></div>
      <svg class="hand" viewBox="0 0 300 120" aria-hidden="true"><path id="hw" d="M10 70 C30 20 50 20 55 60 S75 100 95 55 S125 20 140 60 S165 95 185 50 S215 25 230 60 S260 85 290 45"/></svg>
      <div class="ui-bit undo" id="uiu"><span>↶</span> <small>${T('отменить', 'артка кайтаруу')}</small></div>
      <div class="ui-bit saved" id="uis"><span>✓</span> <small>${T('сохранено', 'сакталды')}</small></div></div>
    <div class="nb-cover" id="cover"><span class="mk"></span><b>SABAK<i>+</i></b><small>${T('дневник', 'күндөлүк')}</small></div>
  </div></div>
  <div class="wzs-fin" id="wzs-fin" role="img" aria-label="SABAK+"><svg class="sig" viewBox="0 0 640 170" aria-hidden="true"><text x="50%" y="62%" text-anchor="middle" dominant-baseline="middle">SABAK+</text></svg></div>
  <button type="button" class="wzs-skip" data-wz="splash-skip">${T('Пропустить', 'Өткөрүп жиберүү')} ›</button>`;
}
function renderSplash() {
  W.phase = 'splash'; root.className = 'wz wz-splash';
  root.style.setProperty('--horn', hornTile());
  root.innerHTML = splashHTML();
  const hw = $('#hw'), hand = $('.hand'); try { hand.style.setProperty('--len', Math.ceil(hw.getTotalLength())); } catch {}
  const nb = $('#nb'), cells = [...root.querySelectorAll('.cells i')], stage = $('#wzs-stage'), fin = $('#wzs-fin'), sig = $('.sig');
  const END = 7.0;
  const paint = t => {
    const p = seg(t, 0, 3.3);
    setv(nb, '--open', ease.inOut(seg(p, .12, .6)));
    setv(hand, '--inkp', seg(p, .58, .78));
    cells.forEach((c, i) => setv(c, '--c', ease.out(seg(p, .68 + i * .04, .78 + i * .04))));
    setv($('#uig'), '--o', seg(p, .64, .72)); setv($('#uiu'), '--o', seg(p, .82, .9)); setv($('#uis'), '--o', seg(p, .88, .96));
    const f = seg(t, 3.25, 3.85);
    stage.style.opacity = (1 - f).toFixed(3); fin.style.opacity = f.toFixed(3);
    setv(sig, '--w', ease.inOut(seg(t, 3.6, 5.6)));   // контур
    setv(sig, '--fill', seg(t, 5.4, 6.1));            // заливка
  };
  const go2 = () => {
    if (W.phase !== 'splash') return;
    if (reduced()) { paint(END); const b = $('.wzs-skip'); if (b) { b.textContent = T('Продолжить', 'Улантуу') + ' ›'; b.classList.add('on'); b.focus(); } return; }
    paint(0); const t0 = performance.now();
    const frame = now => { if (W.phase !== 'splash') return; const t = (now - t0) / 1000; paint(t); if (t < END) W.raf = requestAnimationFrame(frame); else renderWizard(); };
    W.raf = requestAnimationFrame(frame);
  };
  // шрифт нужен до первого кадра, иначе контур слова «прыгнет»
  const f = document.fonts && document.fonts.load ? Promise.race([document.fonts.load('700 150px Oswald'), new Promise(r => setTimeout(r, 1200))]) : Promise.resolve();
  f.catch(() => {}).then(go2);
}

