    <ol class="wz-first">${items.map(([r, a, b]) => `<li><span>${esc(T(a, b))}</span><button type="button" class="wz-b" data-wz="go" data-r="${r}">${T('Открыть', 'Ачуу')} ›</button></li>`).join('')}</ol>
